const $=s=>document.querySelector(s), colors=['#e6dfc9','#2c6dba','#329579','#b7473e','#343843','#d8ab46'],names=['다이아몬드','사파이어','에메랄드','루비','오닉스','황금'],zero=()=>[0,0,0,0,0,0],sum=a=>a.reduce((s,x)=>s+x,0),shuffle=a=>{let b=a.slice();for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b};
