const arts=[[148,151,58,90],[216,150,66,91],[298,151,64,91],[376,154,62,89],[139,251,62,87],[215,251,65,86],[294,252,65,86],[375,254,60,83],[131,354,64,96],[212,354,65,94],[292,357,64,91],[372,358,61,89]];
