function myTurn(){return game&&!game.over&&game.turn===0&&game.phase==='play'}
function validTake(a){let total=sum(a),p=game.players[game.turn];return a.length===6&&a.every(n=>Number.isInteger(n)&&n>=0)&&total>0&&a[5]===0&&a.every((v,i)=>v<=game.bank[i])&&((total<=3&&a.every(v=>v<=1))||(total===2&&a.some((v,i)=>v===2&&game.bank[i]>=4)))}
