function openCard(id){if(!myTurn())return;let found=locate(id);if(!found)return;let c=found.c,p=game.players[0];$('#cardDialog').innerHTML=`<div class="eyebrow">LEVEL ${c.tier} · ${names[c.color]}</div><h2>${c.points}점의 명성, 영구 보석 1개</h2>${cardHTML(c,false)}<p>${canBuy(p,c)?'지금 구매할 수 있습니다.':'보석을 더 모으면 구매할 수 있습니다.'} ${found.reserved?'내 예약 카드입니다.':'예약하면 황금 칩 1개를 받습니다 (은행에 있을 때).'}</p><div class="actions"><button class="primary" onclick="buy(${id})" ${canBuy(p,c)?'':'disabled'}>구매하기</button>${!found.reserved?`<button onclick="reserve(${id})" ${p.reserved.length>=3?'disabled':''}>예약하기</button>`:''}</div><button class="subtle" onclick="document.querySelector('#cardDialog').close()">테이블로 돌아가기</button>`;$('#cardDialog').showModal()}
