function reserve(id){if(game.over||game.phase!=='play')return false;let f=locate(id);if(!f||f.reserved)return false;let p=game.players[game.turn];if(p.reserved.length>=3)return false;removeCard(f);doReserve(f.c);return true}
function reserveDeck(t){if(!myTurn()||!game.decks[t].length||game.players[0].reserved.length>=3)return;$('#cardDialog').innerHTML=`<h2>${t+1}단계 카드 예약</h2><p>더미의 맨 위 카드를 보지 않고 예약합니다.</p><div class="actions"><button class="primary" onclick="confirmDeck(${t})">예약하기</button><button onclick="document.querySelector('#cardDialog').close()">취소</button></div>`;$('#cardDialog').showModal()}
function confirmDeck(t){if(!myTurn()||game.players[0].reserved.length>=3||!game.decks[t].length)return;doReserve(game.decks[t].shift())}
function doReserve(c){let p=game.players[game.turn];p.reserved.push(c);if(game.bank[5]){game.bank[5]--;p.tokens[5]++}record(`${c.tier}단계 카드 예약`);$('#cardDialog').close();tone('card');finish()}
function take(a){if(!validTake(a)||game.phase!=='play'||game.over)return false;let p=game.players[game.turn];a.forEach((n,i)=>{p.tokens[i]+=n;game.bank[i]-=n});record(a.map((n,i)=>n?`${names[i]} ${n}`:'').filter(Boolean).join(' · ')+' 획득');if(game.turn===0)animateTokens(a);selected=zero();tone('chip');finish();return true}
function animateTokens(a){a.forEach((n,i)=>{if(!n)return;let from=$('#bank').children[i].getBoundingClientRect(),to=$('#player').getBoundingClientRect(),e=document.createElement('div');e.className='fly-chip';e.style.cssText=`--c:${colors[i]};left:${from.x+10}px;top:${from.y}px`;document.body.append(e);requestAnimationFrame(()=>requestAnimationFrame(()=>{e.style.transform=`translate(${to.x+200-from.x}px,${to.y+40-from.y}px) rotate(200deg)`;e.style.opacity='0'}));setTimeout(()=>e.remove(),750)})}
function record(msg){let p=game.players[game.turn];p.last=msg;logs.push(`${p.name}: ${msg}`)}
function finish(){let p=game.players[game.turn];if(sum(p.tokens)>10){if(game.turn===0){game.phase='return';render();showReturnDialog();return}const snapshot=SplendorAI.snapshot(game,game.turn);SplendorAI.trim(snapshot);p.tokens=snapshot.p.tokens;game.bank=snapshot.bank;}checkNoble()}
function showReturnDialog(){
  const p=game.players[0],excess=sum(p.tokens)-10;
  $('#choice').innerHTML='<h2>보석 '+excess+'개를 반환하세요</h2><p>황금까지 합쳐 10개를 남겨야 턴이 끝납니다. 반환할 색을 누르세요.</p><div class="return-options">'+p.tokens.map((v,i)=>'<button onclick="returnToken('+i+')" '+(!v?'disabled':'')+'>'+gem(i)+' '+names[i]+' '+v+'</button>').join('')+'</div>';
  if(!$('#choice').open)$('#choice').showModal();
}
function returnToken(i){if(game.turn!==0||game.phase!=='return'||!game.players[0].tokens[i])return;game.players[0].tokens[i]--;game.bank[i]++;tone('chip');if(sum(game.players[0].tokens)===10){$('#choice').close();game.phase='play';checkNoble()}else{render();showReturnDialog()}}
function checkNoble(){let p=game.players[game.turn],eligible=game.nobles.filter(n=>n.cost.every((v,i)=>p.bonus[i]>=v));if(eligible.length>1&&game.turn===0){game.phase='noble';render();$('#choice').innerHTML='<h2>귀족의 방문</h2><p>이번 턴에 방문할 귀족을 한 명 선택하세요.</p>'+eligible.map(n=>`<button class="primary" style="margin:6px 0" onclick="chooseNoble(${n.id})">${n.cost.map((v,i)=>v?names[i]+' '+v:'').filter(Boolean).join(' · ')} → 3점</button>`).join('');$('#choice').showModal();return}if(eligible.length)awardNoble(eligible[0]);endTurn()}
function awardNoble(n){let p=game.players[game.turn];p.nobles.push(n);p.points+=3;game.nobles=game.nobles.filter(x=>x.id!==n.id);record('귀족 방문 · 명성 +3')}
function chooseNoble(id){if(game.phase!=='noble')return;let n=game.nobles.find(n=>n.id===id);if(!n||!n.cost.every((v,i)=>game.players[0].bonus[i]>=v))return;awardNoble(n);game.phase='play';$('#choice').close();endTurn()}
function endTurn(){game.phase='play';if(game.players[game.turn].points>=15)game.final=true;game.turn++;if(game.turn===game.players.length){game.turn=0;game.round++;if(game.final){game.over=true;render();let best=Math.max(...game.players.map(p=>p.points)),fewest=Math.min(...game.players.filter(p=>p.points===best).map(p=>p.cards.length)),w=game.players.filter(p=>p.points===best&&p.cards.length===fewest);$('#choice').innerHTML=`<div class="eyebrow">THE TABLE IS COMPLETE</div><h1>${w.map(p=>p.name).join(' · ')}${w.length>1?' 공동':''} 승리</h1><p>${best}점의 명성으로 테이블의 주인공이 되었습니다.</p>${game.players.map(p=>`<p>${p.name} — ${p.points}점 · 카드 ${p.cards.length}장</p>`).join('')}<button class="primary" onclick="document.querySelector('#choice').close();document.querySelector('#setup').showModal()">새 게임</button><button class="subtle" onclick="document.querySelector('#choice').close()">테이블 보기</button>`;$('#choice').showModal();tone('start');return}}render();if(game.turn)queueAI()}
function marketCards(){return game.market.flat().filter(Boolean)}
function hasAction(p){return game.bank.slice(0,5).some(v=>v>0)||[...marketCards(),...p.reserved].some(c=>canBuy(p,c))||(p.reserved.length<3&&(marketCards().length||game.decks.some(d=>d.length)))}
function queueAI(){let g=generation;aiTimer=setTimeout(()=>{if(g!==generation||!game.turn||game.over)return;aiMove()},1000+Math.random()*600)}
function cardValue(p,c){let need=c.cost.map((v,i)=>Math.max(0,v-p.bonus[i]-p.tokens[i])),dist=Math.max(0,sum(need)-p.tokens[5]);let noble=game.nobles.reduce((s,n)=>s+(n.cost[c.color]>p.bonus[c.color]?0.4:0),0);return c.points*2.4+3/(1+p.bonus[c.color])+noble-dist*(p.level==='상'?1.6:1)-sum(c.cost)*.08+(p.points+c.points>=15?20:0)}
function aiMove(){
  if(game.over||game.phase!=='play')return;
  const p=game.players[game.turn],state=SplendorAI.snapshot(game,game.turn);
  let action;
  if(p.level==='최상'||p.level==='마스터'){
    action=SplendorAI.choose(game,game.turn,p.level);
  }else{
    const options=SplendorAI.actions(state), all=[...marketCards(),...p.reserved];
    const purchases=all.filter(c=>canBuy(p,c));
    if(purchases.length&&(p.level!=='하'||Math.random()<.75)){
      purchases.sort((a,b)=>cardValue(p,b)-cardValue(p,a));
      action={type:'buy',id:(p.level==='하'?shuffle(purchases)[0]:purchases[0]).id};
    }else{
      const takes=options.filter(a=>a.type==='take');
      if(p.level==='하')action=shuffle(takes)[0];
      else{
        const target=all.slice().sort((a,b)=>cardValue(p,b)-cardValue(p,a))[0];
        const needs=target?target.cost.map((v,i)=>Math.max(0,v-p.bonus[i]-p.tokens[i])):zero();
        takes.sort((a,b)=>{
          const value=x=>sum(x.tokens.map((n,i)=>Math.min(n,needs[i])*3+n*.15))-
            Math.max(0,sum(p.tokens)+sum(x.tokens)-10)*1.5;
          return value(b)-value(a);
        });
        action=takes[0];
        if(p.level==='상'&&p.reserved.length<3&&game.bank[5]&&target&&!p.reserved.includes(target)&&sum(needs)<=2)
          action={type:'reserve',id:target.id};
      }
      action=action||options[0];
    }
  }
  if(action?.type==='buy'){buy(action.id);return}
  if(action?.type==='reserve'){reserve(action.id);return}
  if(action?.type==='take'){take(action.tokens);return}
  // A blind reservation is still legal if all visible cards are gone.
  const tier=game.decks.findIndex(d=>d.length);
  if(p.reserved.length<3&&tier>=0){doReserve(game.decks[tier].shift());return}
  record('가능한 행동이 없어 턴 넘김');endTurn();
}
function audio(){if(!ctx)ctx=new(window.AudioContext||window.webkitAudioContext)();if(ctx.state==='suspended')ctx.resume();return ctx}
function note(f,d,v=.07,type='sine',delay=0){let ac=audio(),o=ac.createOscillator(),g=ac.createGain(),t=ac.currentTime+delay;o.type=type;o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(v,t+.02);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g);g.connect(ac.destination);o.start(t);o.stop(t+d)}
function tone(t){if(!soundOn)return;try{if(t==='chip'){note(1300,.09,.04);note(900,.1,.025,'sine',.04)}else if(t==='card'){note(220,.12,.035,'triangle');note(330,.15,.025,'triangle',.07)}else[261.6,329.6,392,523].forEach((f,i)=>note(f,.6,.035,'sine',i*.13))}catch{}}
function music(){clearInterval(musicTimer);if(!musicOn)return;let n=0;const chords=[[130.81,164.81,196],[110,130.81,164.81],[87.31,130.81,174.61],[98,146.83,196]];const tick=()=>{if(!musicOn)return;let c=chords[Math.floor(n/4)%4];note(c[n%3],2.1,.025,'sine');note(c[(n+1)%3]*2,1.7,.012,'triangle',.4);n++};tick();musicTimer=setInterval(tick,950)}
function setupLevels(){let n=+$('#count').value;$('#levels').innerHTML=Array.from({length:n},(_,i)=>`<div><label for="level${i}">컴퓨터 ${i+1}</label><select id="level${i}"><option>하</option><option selected>중</option><option>상</option><option>최상</option><option>마스터</option></select></div>`).join('')}
$('#count').onchange=setupLevels;$('#start').onclick=e=>{e.preventDefault();start(Array.from({length:+$('#count').value},(_,i)=>$('#level'+i).value))};$('#settings').onclick=()=>$('#setup').showModal();$('#cancelSetup').onclick=()=>$('#setup').close();$('#rules').onclick=()=>$('#help').showModal();$('#take').onclick=()=>{if(myTurn())take(selected.slice())};$('#clear').onclick=()=>{selected=zero();render()};$('#pass').onclick=()=>{if(myTurn()&&!hasAction(game.players[0]))endTurn()};$('#music').onclick=()=>{musicOn=!musicOn;$('#music').textContent='♫ 음악 '+(musicOn?'켜짐':'꺼짐');$('#music').setAttribute('aria-pressed',musicOn);music()};$('#sound').onclick=()=>{soundOn=!soundOn;$('#sound').textContent='♪ 효과음 '+(soundOn?'켜짐':'꺼짐');$('#sound').setAttribute('aria-pressed',soundOn);tone('chip')};$('#choice').addEventListener('cancel',e=>{if(game.phase==='noble'||game.phase==='return')e.preventDefault()});setupLevels();soundOn=false;start(['중','중']);soundOn=true;$('#setup').showModal();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_splendor_table',description:'현재 스플렌더 게임의 차례, 카드, 보석, 점수를 읽습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>JSON.parse(JSON.stringify(game))});document.modelContext.registerTool({name:'take_splendor_gems',description:'내 차례에 선택한 보석을 가져오고 턴을 완료합니다. 순서는 흰색, 파랑, 초록, 빨강, 검정입니다.',inputSchema:{type:'object',properties:{counts:{type:'array',items:{type:'integer',minimum:0,maximum:2},minItems:5,maxItems:5}},required:['counts'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({counts})=>{if(!Array.isArray(counts)||counts.length!==5||counts.some(n=>!Number.isInteger(n)||n<0||n>2)||!myTurn()||!validTake([...counts,0]))throw Error('현재 가져올 수 없는 보석 조합입니다.');take([...counts,0]);return {turn:game.turn,tokens:game.players[0].tokens,phase:game.phase}}})}catch(e){console.warn('WebMCP unavailable',e)}}
/* Keep every player's information in the same vertical, easy-scan layout. */
const baseRender=render;
render=function(){
  baseRender();
  if(!game)return;
  document.querySelectorAll('#market .card').forEach((el,index)=>{const visible=[...game.market[2],...game.market[1],...game.market[0]].filter(Boolean)[index];if(visible){el.style.setProperty('--bonus-color',colors[visible.color]);el.dataset.bonus=names[visible.color]}});
  document.querySelectorAll('#opponents .opponent').forEach((el,index)=>{const p=game.players[index+1];const old=el.querySelector('.inventory');if(old&&!el.querySelector('.op-bonuses')){const bonus=document.createElement('div');bonus.className='op-bonuses';bonus.setAttribute('aria-label','카드 보너스');bonus.innerHTML=p.bonus.slice(0,5).map((v,i)=>`<span class="op-bonus" style="--c:${colors[i]}" title="${names[i]} 카드 보너스">${v}</span>`).join('');old.insertAdjacentElement('afterend',bonus)}});
};
render();
/* Align each colour's gem and card bonus into the same column. */
const previousAlignedRender=render;
render=function(){
  previousAlignedRender();
  if(!game)return;
  const p=game.players[0], sections=document.querySelectorAll('#player .player-section');
  if(sections.length>1){
    sections[0].innerHTML=`<div class="resource-grid"><div class="resource-grid-label">보유 보석 <span>${sum(p.tokens)} / 10</span></div><div class="resource-grid-row">${p.tokens.map((v,i)=>`<button class="p-token" onclick="returnToken(${i})" title="${names[i]}${game.phase==='return'?' 반환':''}">${gem(i)}<b>${v}</b></button>`).join('')}</div><div class="resource-grid-label">카드 보너스 <span>${p.cards.length}장 · 귀족 ${p.nobles.length}명</span></div><div class="resource-grid-row bonus-row">${p.bonus.slice(0,5).map((v,i)=>`<div class="bonus-card" style="--c:${colors[i]}" title="${names[i]} 할인">${v}</div>`).join('')}<div class="bonus-spacer" aria-hidden="true"></div></div></div>`;
    sections[1].style.display='none';
  }
  document.querySelectorAll('#opponents .opponent').forEach((el,index)=>{const op=game.players[index+1];if(el.querySelector('.op-resource-grid'))return;const inv=el.querySelector('.inventory'), bonuses=el.querySelector('.op-bonuses');if(inv&&bonuses){const grid=document.createElement('div');grid.className='op-resource-grid';grid.innerHTML=`<div class="resource-grid-label">보유 보석</div><div class="resource-grid-row">${op.tokens.map((v,i)=>`<span class="mini">${gem(i)}<b>${v}</b></span>`).join('')}</div><div class="resource-grid-label">카드 보너스</div><div class="resource-grid-row bonus-row">${op.bonus.slice(0,5).map((v,i)=>`<span class="op-bonus" style="--c:${colors[i]}">${v}</span>`).join('')}<span class="bonus-spacer"></span></div>`;inv.replaceWith(grid);bonuses.remove()}});
};
render();
